import argparse
import asyncio
from collections import Counter
from datetime import datetime, timezone
import inspect
from pathlib import Path
import sys
from types import SimpleNamespace

from scripts import evaluate, generate, newsroom_judge, newsroom_results, newsroom_stats
from scripts.modules import ROOT, digest
from package_tuning import verify_receipt


WORK = Path(__file__).parent
BASE = ROOT / "evals/runs/newsroom-primary-v1"


def write_exact(path, value):
    if path.exists():
        evaluate.require(evaluate.load_json(path) == value, f"Existing artifact differs: {path.name}")
    else:
        evaluate.write_json(path, value)


def load_protocol():
    evaluate.require(sys.flags.optimize == 0, "Receipt verification requires assertions enabled")
    protocol = evaluate.load_json(ROOT / "evals/newsroom/primary-protocol.json")
    evaluate.verify_seal(protocol, "protocol_sha256")
    design = protocol["design"]
    evaluate.verify_seal(design, "design_sha256")
    evaluate.verify_seal(protocol["auxiliary_randomization"], "draws_sha256")
    evaluate.require(protocol["auxiliary_randomization"]["design_sha256"] == design["design_sha256"],
                     "Auxiliary draws belong to a different frozen design")
    allocation = newsroom_results.validate_allocation(design["allocation"])
    evaluate.require(evaluate.load_json(BASE / "allocation.json") == allocation, "Local allocation changed")
    evaluate.require(evaluate.load_json(BASE / "writing-plan.json") == design["writing_plan"], "Writing plan changed")
    for name, source in design["sources"].items():
        evaluate.require(digest((ROOT / name).read_text(encoding="utf-8")) == source["source_sha256"],
                         f"Frozen source changed: {name}")
    for name, source in design["orchestration_sources"].items():
        evaluate.require(digest((WORK / name).read_text(encoding="utf-8")) == source["source_sha256"],
                         f"Frozen orchestration changed: {name}")
    evaluate.require(digest(inspect.getsource(verify_receipt)) == design["receipt_validator"]["source_sha256"],
                     "Frozen receipt validation changed")
    for case in allocation["cases"]:
        text = (ROOT / case["path"]).read_text(encoding="utf-8")
        evaluate.require(digest(text) == case["source_sha256"], f"Frozen reporting packet changed: {case['case_id']}")
    return protocol, design, allocation


def runtime_directory(phase):
    name = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%S%fZ")
    directory = BASE / f"{phase}-runtime-{name}"
    directory.mkdir()
    return directory


def mark_started(protocol):
    path = BASE / "primary-started.json"
    if path.exists():
        value = evaluate.load_json(path)
        evaluate.require(value["protocol_sha256"] == protocol["protocol_sha256"], "Started protocol changed")
    else:
        evaluate.write_json(path, {
            "protocol_sha256": protocol["protocol_sha256"],
            "started_at": datetime.now(timezone.utc).isoformat(),
            "instruction_changes_after_start_permitted": False,
        })


async def writing(resume):
    protocol, design, allocation = load_protocol()
    evaluate.require(not (BASE / "judgment-plan.json").exists(), "Writing is closed after judgment preparation")
    plan, jobs = generate.load_jobs(ROOT, BASE / "writing-plan.json")
    expected = {
        case["writing_job_ids"][variant]: (case, variant)
        for case in allocation["cases"] for variant in allocation["variants"]
    }
    evaluate.require({job["id"] for job in jobs} == set(expected), "Writing job coverage changed")
    for job in jobs:
        case, variant = expected[job["id"]]
        evaluate.require(job["model"] == case["writer"]
                         and job["request_value"]["request_sha256"] == case["request_sha256"][variant],
                         "Writing request/model binding changed")
    config = design["acquisition"]
    async with generate.LiveTransport(
        runtime_directory("writing"), set(allocation["writers"]), config["timeout_seconds"]
    ) as transport:
        evaluate.require(transport.settings == allocation["model_settings"], "Discovered writing settings changed")
        mark_started(protocol)
        result = await generate.run_jobs(
            ROOT, plan, jobs, BASE / "writing", transport, concurrency=config["concurrency"],
            order_seed=allocation["randomness"]["generation_order_seed"], resume=resume,
        )
    print(evaluate.canonical({
        "phase": "writing", "status": result["status"],
        "captured": result["captured_jobs"], "planned": result["planned_jobs"],
    }))
    return int(result["status"] != "captured")


def writing_snapshot(allocation):
    records, states = {}, {}
    planned_jobs = {job["id"]: job for job in evaluate.load_json(BASE / "writing-plan.json")["jobs"]}
    for case in allocation["cases"]:
        for variant in allocation["variants"]:
            job = case["writing_job_ids"][variant]
            target = BASE / "writing" / job
            record_path = target / "record.json"
            capture_path, failure_path = target / "capture.json", target / "failure.json"
            if record_path.exists():
                evaluate.require(capture_path.exists() and not failure_path.exists(), "Conflicting/incomplete writer record")
                record = evaluate.validate_result(ROOT, evaluate.load_json(record_path))
                evaluate.require(
                    record["request"]["request_sha256"] == case["request_sha256"][variant]
                    and record["request"]["case_sha256"] == case["case_sha256"]
                    and record["model"] == case["writer"]
                    and record["family"] == planned_jobs[job]["family"]
                    and record["settings"] == allocation["model_settings"][case["writer"]],
                    "Captured writer record differs from the frozen job",
                )
                capture = evaluate.load_json(capture_path)
                verify_receipt(capture, record["request"]["prompt"], record["response"], record["model"])
                records[job] = record
                states[job] = {
                    "status": "captured", "result_sha256": record["result_sha256"],
                    "capture_sha256": digest(evaluate.canonical(capture)),
                }
            else:
                states[job] = {
                    "status": "failed" if failure_path.exists() else "incomplete" if target.exists() else "not_started",
                    "capture_present": capture_path.exists(),
                    "failure": evaluate.load_json(failure_path) if failure_path.exists() else None,
                }
    return records, states


def prepare_judgments():
    protocol, design, allocation = load_protocol()
    evaluate.require((BASE / "writing/summary.json").exists(), "Writing acquisition has not produced a finished summary")
    evaluate.require(not (BASE / "judging").exists(), "Judgment acquisition already started")
    records, states = writing_snapshot(allocation)
    record_map = {value["result_sha256"]: value for value in records.values()}
    case_map = {case["case_id"]: case for case in allocation["cases"]}
    prepared, unavailable = [], []
    (BASE / "judgment-requests").mkdir(exist_ok=True)
    for slot in allocation["judgment_slots"]:
        case = case_map[slot["case_id"]]
        needed = allocation["variants"] if slot["kind"] == "preference" else [slot["variant"]]
        missing = [case["writing_job_ids"][variant] for variant in needed if case["writing_job_ids"][variant] not in records]
        if missing:
            unavailable.append({"id": slot["id"], "missing_writing_jobs": missing})
            continue
        if slot["kind"] == "preference":
            full = records[case["writing_job_ids"]["full"]]
            bare = records[case["writing_job_ids"]["bare-task"]]
            first, second = (full, bare) if case["full_is_a"] else (bare, full)
            request = newsroom_judge.preference_request(ROOT, first, second, slot["judge"])
        else:
            request = newsroom_judge.pointwise_request(
                ROOT, records[case["writing_job_ids"][slot["variant"]]], slot["judge"],
            )
        newsroom_judge.validate_request(ROOT, request, record_map)
        relative = f"judgment-requests/{slot['id']}.json"
        write_exact(BASE / relative, request)
        prepared.append({"id": slot["id"], "path": relative, "request_sha256": digest(evaluate.canonical(request))})
    manifest = evaluate.seal({
        "schema_version": 1, "kind": "prepared-primary-judgment-plan",
        "protocol_sha256": protocol["protocol_sha256"],
        "writing_states": states, "writing_snapshot_sha256": digest(evaluate.canonical(states)),
        "prepared_jobs": prepared, "unavailable_slots": unavailable,
        "planned_slots": len(allocation["judgment_slots"]),
    }, "preparation_sha256")
    evaluate.require(len(prepared) + len(unavailable) == manifest["planned_slots"], "Lost planned judgment slots")
    write_exact(BASE / "judgment-plan.json", manifest)
    print(evaluate.canonical({
        "phase": "judgment-preparation", "planned": manifest["planned_slots"],
        "prepared": len(prepared), "unavailable": len(unavailable), "model_calls": 0,
    }))
    return 0


def load_judgments(protocol, allocation):
    manifest = evaluate.load_json(BASE / "judgment-plan.json")
    evaluate.verify_seal(manifest, "preparation_sha256")
    evaluate.require(manifest["protocol_sha256"] == protocol["protocol_sha256"], "Judgment protocol changed")
    records, states = writing_snapshot(allocation)
    evaluate.require(states == manifest["writing_states"], "Writing snapshot changed after judgment preparation")
    record_map = {value["result_sha256"]: value for value in records.values()}
    jobs = []
    for row in manifest["prepared_jobs"]:
        request = evaluate.load_json(BASE / row["path"])
        evaluate.require(digest(evaluate.canonical(request)) == row["request_sha256"], "Prepared judgment changed")
        newsroom_judge.validate_request(ROOT, request, record_map)
        jobs.append({"id": row["id"], "request": request})
    return manifest, records, record_map, jobs


async def judging(resume):
    protocol, design, allocation = load_protocol()
    manifest, records, record_map, jobs = load_judgments(protocol, allocation)
    evaluate.require(bool(jobs), "No valid writing inputs; no judgments can be acquired")
    config = design["acquisition"]
    async with generate.LiveTransport(
        runtime_directory("judging"), set(allocation["judges"]), config["timeout_seconds"]
    ) as transport:
        evaluate.require(transport.settings == allocation["model_settings"], "Discovered judge settings changed")
        result = await newsroom_judge.run_jobs(
            ROOT, jobs, record_map, BASE / "judging", transport,
            concurrency=config["concurrency"], order_seed=allocation["randomness"]["judgment_order_seed"],
            resume=resume, continue_unstarted=resume,
        )
    print(evaluate.canonical({
        "phase": "judging", "status": result["status"], "captured": result["captured_jobs"],
        "planned": result["planned_jobs"], "continuation_index": result["continuation_index"],
    }))
    return 0 if result["status"] == "captured" else 1


def report():
    protocol, design, allocation = load_protocol()
    manifest, records, record_map, jobs = load_judgments(protocol, allocation)
    evaluate.require((BASE / "judging/summary.json").exists(), "Judgment acquisition has no finished summary")
    verified = asyncio.run(newsroom_judge.run_jobs(
        ROOT, jobs, record_map, BASE / "judging", SimpleNamespace(settings=allocation["model_settings"]),
        concurrency=design["acquisition"]["concurrency"],
        order_seed=allocation["randomness"]["judgment_order_seed"], resume=True,
    ))
    case_map = {row["case_id"]: row for row in allocation["cases"]}
    slot_map = {row["id"]: row for row in allocation["judgment_slots"]}
    preferences = {row["id"]: None for row in allocation["judgment_slots"] if row["kind"] == "preference"}
    pointwise = {row["id"]: None for row in allocation["judgment_slots"] if row["kind"] == "pointwise"}
    responses = {
        job: records[job]["response"] if job in records else None
        for case in allocation["cases"] for job in case["writing_job_ids"].values()
    }
    states = {row["id"]: {"status": "unavailable-writing-input"} for row in manifest["unavailable_slots"]}
    for job in jobs:
        target = BASE / "judging" / job["id"]
        assessment_path, failure_path = target / "assessment.json", target / "failure.json"
        if verified["jobs"][job["id"]]["status"] != "captured":
            failure = evaluate.load_json(failure_path) if failure_path.exists() else None
            stage_status = {
                "assessment": "invalid-response", "transport": "transport-failed",
                "capture_validation": "invalid-capture", "artifact": "artifact-failed",
            }
            states[job["id"]] = {
                "status": stage_status[failure["stage"]] if failure is not None else (
                    "incomplete" if target.exists() else "not_started"
                ),
                "capture_present": (target / "capture.json").exists(),
                "failure": failure,
            }
            continue
        evaluate.require(not failure_path.exists(), "Conflicting assessment and failure artifacts")
        evaluate.require(evaluate.load_json(target / "request.json") == job["request"], "Captured judgment request changed")
        capture = evaluate.load_json(target / "capture.json")
        slot = slot_map[job["id"]]
        verify_receipt(capture, job["request"]["prompt"], capture["response"], slot["judge"])
        assessment, evidence = newsroom_judge.parse_assessment(job["request"], capture["response"])
        stored = evaluate.load_json(assessment_path)
        evaluate.require(stored["assessment"] == assessment and stored["evidence"] == evidence,
                         "Stored assessment differs from the frozen strict parser")
        evaluate.require(stored["response_sha256"] == capture["response_sha256"], "Assessment response binding changed")
        if slot["kind"] == "preference":
            preferences[slot["id"]] = newsroom_results.score_preference(
                assessment["winner"], case_map[slot["case_id"]]["full_is_a"],
            )
        else:
            pointwise[slot["id"]] = newsroom_results.Pointwise(assessment["level"], assessment["fidelity"])
        states[slot["id"]] = {
            "status": "valid", "response_sha256": capture["response_sha256"],
            "capture_sha256": digest(evaluate.canonical(capture)),
        }
    draws = {
        name: newsroom_stats.FamilyDraw(**value)
        for name, value in protocol["auxiliary_randomization"]["draws"].items()
    }
    summary = newsroom_results.summarize(allocation, draws, preferences, pointwise, responses)
    result = evaluate.seal({
        "schema_version": 1, "kind": "verified-primary-newsroom-report",
        "protocol_sha256": protocol["protocol_sha256"],
        "judgment_preparation_sha256": manifest["preparation_sha256"],
        "judgment_states": states, "judgment_state_counts": dict(Counter(row["status"] for row in states.values())),
        "summary": summary,
    }, "report_sha256")
    write_exact(BASE / "analysis.json", result)
    print(evaluate.canonical({
        "phase": "analysis", "primary_preference": summary["primary_preference"],
        "per_judgment_counts": summary["per_judgment_counts"],
        "judgment_state_counts": result["judgment_state_counts"],
    }))
    return 0


def main():
    parser = argparse.ArgumentParser(description="Execute the frozen, model-only primary newsroom study.")
    parser.add_argument("phase", choices=("writing", "prepare-judgments", "judging", "report"))
    parser.add_argument("--resume", action="store_true")
    args = parser.parse_args()
    evaluate.require(not args.resume or args.phase in ("writing", "judging"), "Resume only applies to acquisition")
    if args.phase == "writing":
        return asyncio.run(writing(args.resume))
    if args.phase == "judging":
        return asyncio.run(judging(args.resume))
    return prepare_judgments() if args.phase == "prepare-judgments" else report()


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except (evaluate.DocumentError, OSError, AssertionError) as error:
        print(f"primary: {error}", file=sys.stderr)
        raise SystemExit(2) from error
